using LUMAR_ERP_API_V2.DTOs.Purchasing;using LUMAR_ERP_API_V2.Services;using Microsoft.AspNetCore.Mvc;namespace LUMAR_ERP_API_V2.Controllers;[ApiController][Route("purchasing")]public sealed class PurchasingController(IPurchasingService s):ControllerBase{[HttpGet("orders")]public async Task<ActionResult<IReadOnlyList<PurchaseOrderListDto>>> Orders(CancellationToken c)=>Ok(await s.GetOrdersAsync(c));[HttpGet("orders/{id:int}")]public async Task<ActionResult<PurchaseOrderDetailsDto>> Order(int id,CancellationToken c){var x=await O(id,c);return x.Error??Ok(x.Value!);}[HttpGet("orders/{id:int}/items")]public async Task<ActionResult<IReadOnlyList<PurchaseOrderItemDto>>> Items(int id,CancellationToken c){var x=await O(id,c);return x.Error??Ok(await s.GetOrderItemsAsync(id,c));}[HttpGet("orders/{id:int}/receipts")]public async Task<ActionResult<IReadOnlyList<GoodsReceiptDto>>> ReceiptsForOrder(int id,CancellationToken c){var x=await O(id,c);return x.Error??Ok(await s.GetOrderReceiptsAsync(id,c));}[HttpGet("receipts")]public async Task<ActionResult<IReadOnlyList<GoodsReceiptDto>>> Receipts(CancellationToken c)=>Ok(await s.GetReceiptsAsync(c));[HttpGet("receipts/{id:int}")]public async Task<ActionResult<GoodsReceiptDto>> Receipt(int id,CancellationToken c){var x=await R(id,c);return x.Error??Ok(x.Value!);}[HttpGet("receipts/{id:int}/items")]public async Task<ActionResult<IReadOnlyList<GoodsReceiptItemDto>>> ReceiptItems(int id,CancellationToken c){var x=await R(id,c);return x.Error??Ok(await s.GetReceiptItemsAsync(id,c));}[HttpGet("invoices")]public async Task<ActionResult<IReadOnlyList<PurchasingInvoiceDto>>> Invoices(CancellationToken c)=>Ok(await s.GetInvoicesAsync(c));[HttpGet("invoices/{id:int}")]public async Task<ActionResult<PurchasingInvoiceDto>> Invoice(int id,CancellationToken c){var x=await I(id,c);return x.Error??Ok(x.Value!);}[HttpGet("payments")]public async Task<ActionResult<IReadOnlyList<PurchasingPaymentDto>>> Payments(CancellationToken c)=>Ok(await s.GetPaymentsAsync(c));[HttpGet("payments/{id:int}")]public async Task<ActionResult<PurchasingPaymentDto>> Payment(int id,CancellationToken c){var x=await P(id,c);return x.Error??Ok(x.Value!);}[HttpGet("payments/{id:int}/allocations")]public async Task<ActionResult<IReadOnlyList<PurchasingPaymentAllocationDto>>> Allocations(int id,CancellationToken c){var x=await P(id,c);return x.Error??Ok(await s.GetAllocationsAsync(id,c));}[HttpPost][HttpPut("{id:int}")][HttpDelete("{id:int}")]public IActionResult Disabled()=>StatusCode(405,"Purchasing writes are disabled while LUMAR_ERP is read-only.");private async Task<(PurchaseOrderDetailsDto? Value,ActionResult? Error)> O(int i,CancellationToken c){if(i<=0)return(null,BadRequest("Purchase order id must be positive."));var x=await s.GetOrderAsync(i,c);return x is null?(null,NotFound()):(x,null);}private async Task<(GoodsReceiptDto? Value,ActionResult? Error)> R(int i,CancellationToken c){if(i<=0)return(null,BadRequest("Goods receipt id must be positive."));var x=await s.GetReceiptAsync(i,c);return x is null?(null,NotFound()):(x,null);}private async Task<(PurchasingInvoiceDto? Value,ActionResult? Error)> I(int i,CancellationToken c){if(i<=0)return(null,BadRequest("Supplier invoice id must be positive."));var x=await s.GetInvoiceAsync(i,c);return x is null?(null,NotFound()):(x,null);}private async Task<(PurchasingPaymentDto? Value,ActionResult? Error)> P(int i,CancellationToken c){if(i<=0)return(null,BadRequest("Supplier payment id must be positive."));var x=await s.GetPaymentAsync(i,c);return x is null?(null,NotFound()):(x,null);}}